"use strict";

(async () => {
  const checks = [];
  function check(condition, name) { if (!condition) throw new Error(name); checks.push(name); }
  const sleep = (ms = 200) => new Promise((resolve) => setTimeout(resolve, ms));
  const hl = (root) => root.querySelectorAll(".lexis-web-hl");
  const nativeSelection = window.getSelection();
  const select = (node, start, end) => { nativeSelection.setBaseAndExtent(node, start, node, end); handleSelectionChange(); };
  try {
    await sleep();
    check(hl(document).length === 1 && hl(fixturePanel.root).length === 2 && hl(fixtureNested.root).length === 1, "initial page, shadow and nested highlights");
    const reading = fixturePanel.root.querySelector(".cue-text");
    const textarea = fixturePanel.root.querySelector("textarea");
    check(!hl(textarea).length && !hl(fixturePanel.root.querySelector('[contenteditable]')).length && !hl(fixturePanel.root.querySelector('#hidden')).length, "hidden text and editors untouched");
    check(textarea.value === "Lexis original source" && reading.textContent === "Lexis welcomes novel.", "subtitle text and source unchanged");
    check(!hl(fixtureOptOut.root).length && !hl(fixtureClosed).length, "opt-out and closed roots excluded");
    const screenText = fixtureOverlay.root.querySelector('.subtitle-text');
    check(hl(screenText).length === 1 && screenText.getAttribute('aria-hidden') === 'true', "visible screen captions highlight without modifying accessibility metadata");
    check(getComputedStyle(screenText).userSelect === 'text' && getComputedStyle(hl(screenText)[0]).pointerEvents === 'auto', "screen caption selection and pointer targeting preserved");
    const screenNode = screenText.lastChild;
    const screenStart = screenNode.nodeValue.indexOf('screenword');
    select(screenNode, screenStart, screenStart + 10);
    onSelect();
    check(selBtn?.dataset.word === 'screenword', "selection-add pill appears for video screen captions");
    const originalPill = selBtn, originalPosition = selBtn.getBoundingClientRect();
    await chrome.storage.local.set({ selectionPillOffset: {x:40,y:30} });
    const shiftedPosition = selBtn.getBoundingClientRect();
    const expectedPosition = LexisPillPosition.positionBrowserSelectionPill(pageSelection().getRangeAt(0).getBoundingClientRect(),
      {width:selBtn.offsetWidth,height:selBtn.offsetHeight},{width:document.documentElement.clientWidth,height:document.documentElement.clientHeight},{x:40,y:30});
    check(selBtn === originalPill && Math.abs(shiftedPosition.left-expectedPosition.left)<1 && Math.abs(shiftedPosition.top-expectedPosition.top)<1 && shiftedPosition.top!==originalPosition.top,
      "browser-local offsets reposition the existing pill immediately without rebuilding it");
    check(nativeSelection.toString() === 'screenword' && fixtureStore.styleConfig.selectionPillOffset === undefined,
      "position changes preserve the composed selection and do not modify Obsidian style data");
    await chrome.storage.local.set({ selectionPillOffset: {x:0,y:0} });
    const source = LexisWebSource.capture(screenNode);
    check(source.title.endsWith('01:23') && source.url === location.href, "screen source records its player time and keeps unknown-platform URL unchanged");
    const pillAdd = selBtn.querySelector('button');
    fixtureVideo.currentTime = 145;
    nativeSelection.removeAllRanges();
    pillAdd.dispatchEvent(new MouseEvent('click', { bubbles: true }));
    await sleep();
    check(fixtureRequests.find((request) => request.type === 'add')?.payload.title.endsWith('01:23'), "pill freezes source time at selection rather than later submission");
    check(hl(screenText).length === 2, "adding a screen-caption word immediately highlights it");
    screenText.textContent = 'Lexis new screen caption.';
    await sleep();
    check(hl(screenText).length === 1, "changing visible caption rehighlights without scanning the drag handle");
    screenText.hidden = true;
    screenText.textContent = 'Lexis hidden screen caption.';
    await sleep();
    check(!hl(screenText).length, "genuinely hidden screen captions remain untouched");
    screenText.hidden = false;
    await sleep();
    check(hl(screenText).length === 1, "showing caption restores highlight");
    const screenMark = hl(screenText)[0];
    screenMark.dispatchEvent(new MouseEvent('mouseover', { bubbles: true, composed: false }));
    await sleep(350);
    check(popHost?.isConnected, "screen caption hover opens a detail card");
    removePop();
    check(fixturePanel.root.adoptedStyleSheets.includes(fixtureOriginalSheet) && fixturePanel.root.adoptedStyleSheets.length === 2, "host stylesheet preserved with shared highlight stylesheet");
    const span = reading.querySelector(".lexis-web-hl");
    check(getComputedStyle(span).textDecorationThickness === "1px" && getComputedStyle(span).color === "rgb(21, 32, 43)", "shadow highlight style applied without changing text color");

    const after = fixtureHost(document.body);
    after.root.innerHTML = "<p>Lexis inserted later</p>";
    await sleep();
    check(hl(after.root).length === 1, "dynamically inserted shadow root discovered");
    const lateHost = document.createElement("div");
    document.body.appendChild(lateHost);
    await sleep();
    const lateRoot = lateHost.attachShadow({ mode: "open" });
    lateRoot.innerHTML = "<p>Lexis attached after insertion</p>";
    lateRoot.querySelector('p').dispatchEvent(new MouseEvent("mouseover", { bubbles: true, composed: true }));
    await sleep();
    check(hl(lateRoot).length === 1, "late-attached roots discovered on component entry without polling");
    reading.textContent = "Lexis updated transcript.";
    await sleep();
    check(hl(reading).length === 1, "transcript replacement rehighlighted");
    reading.hidden = true;
    reading.textContent = "Lexis being edited.";
    textarea.hidden = false;
    textarea.focus();
    await sleep();
    check(!hl(reading).length && !hl(textarea).length, "editing mode does not wrap hidden reading layer or textarea");
    textarea.blur();
    textarea.hidden = true;
    reading.hidden = false;
    await sleep();
    check(hl(reading).length === 1 && textarea.value === "Lexis original source", "saving reading mode restores highlight and preserves edit value");

    reading.textContent = "Lexis welcomes novel.";
    await sleep();
    const novel = reading.lastChild;
    const start = novel.nodeValue.indexOf("novel");
    select(novel, start, start + 5);
    const snapshot = pageSelection();
    check(snapshot.toString() === "novel" && snapshot.anchorNode === novel && snapshot.getRangeAt(0).getBoundingClientRect().width > 0, "shadow selection uses actual text range and geometry");
    onSelect();
    check(selBtn?.dataset.word === "novel", "selection-add pill in subtitle reading layer");
    check(sentenceFromSelection(snapshot) === "Lexis welcomes novel.", "selection context excludes timestamp and editing controls");
    scan(reading);
    check(novel.isConnected && nativeSelection.toString() === "novel", "scan leaves active shadow selection untouched");
    hideSelBtn();
    nativeSelection.removeAllRanges();
    handleSelectionChange();
    await doAdd("novel", "Lexis welcomes novel.", undefined, "10_atom");
    await sleep();
    check(hl(reading).length === 2, "new entries immediately highlight shadow reading text");
    check(fixtureRequests.find((request) => request.type === "add" && request.payload.word === 'novel')?.payload.sentence === "Lexis welcomes novel.", "adding forwards only chosen text and reading context");

    const marked = reading.querySelector(".lexis-web-hl");
    pointerSelecting = false;
    marked.dispatchEvent(new MouseEvent("mouseover", { bubbles: true, composed: true }));
    await sleep(350);
    check(popHost?.shadowRoot?.querySelector('.lexis-web-pop-content')?.textContent === "Lexis definition", "retargeted hover opens existing detail card");
    check(!hl(popHost.shadowRoot).length, "Lexis does not highlight its own card");
    removePop();
    marked.dispatchEvent(new MouseEvent("mouseover", { bubbles: true, composed: false }));
    await sleep(350);
    check(popHost?.isConnected, "hover still works when event is confined to a component tree");
    const cardText = pop.querySelector(".lexis-web-pop-content p").firstChild;
    select(cardText, 0, 5);
    onSelect();
    check(popHost?.isConnected && !selBtn, "card text can be selected without closing card or creating pill");
    nativeSelection.removeAllRanges();
    handleSelectionChange();
    fixturePanel.root.querySelector('.cue-line').dispatchEvent(new Event("scroll"));
    check(!popHost && !selBtn, "shadow scrolling clears detached-position UI");

    await chrome.storage.local.set({ siteDictionaryVisibility: { [currentSite]: { "10_atom": false } } });
    await sleep();
    check(!pageScope.queryAll('.lexis-web-hl').length, "site dictionary toggle unwraps page and all shadow roots");
    await chrome.storage.local.set({ siteDictionaryVisibility: {} });
    await sleep();
    check(hl(document).length && hl(reading).length && hl(fixtureNested.root).length, "site dictionary toggle rehighlights all roots");
    await chrome.storage.local.set({ cfg: { ...fixtureStore.cfg, highlight: false } });
    await sleep();
    check(!pageScope.queryAll('.lexis-web-hl').length, "global highlight toggle clears all roots");
    const disabled = fixtureHost(document.body);
    disabled.root.innerHTML = "<p>another unknown</p>";
    await sleep();
    select(disabled.root.querySelector('p').firstChild, 0, 7);
    onSelect();
    check(selBtn?.dataset.word === "another", "selection-add works for new components while highlights are disabled");
    hideSelBtn();
    nativeSelection.removeAllRanges();
    handleSelectionChange();
    after.host.remove(); disabled.host.remove(); fixtureNested.host.remove();
    await sleep();
    check(!pageScope.roots().includes(after.root) && !pageScope.roots().includes(fixtureNested.root), "detached component observers removed");
    await chrome.storage.local.set({ cfg: { ...fixtureStore.cfg, highlight: true } });
    await sleep();
    check(hl(reading).length > 0, "global highlights restored");
    after.host && document.body.appendChild(after.host);
    await sleep();
    check(hl(after.root).length === 1 && after.root.adoptedStyleSheets.length === 1, "reattached component observed without duplicate style installation");
    document.body.setAttribute("data-lexis-ignore", "");
    document.body.textContent = JSON.stringify({ ok: true, checks });
  } catch (error) {
    document.body.setAttribute("data-lexis-ignore", "");
    document.body.textContent = JSON.stringify({ ok: false, error: error.message, checks });
  }
})();
